import { Component, Input } from "@angular/core";
import { Observable, of } from "rxjs";
import { mockedCoursesList } from "./shared/mocks/mocks";

@Component({
  selector: "app-root",
  templateUrl: "./app.component.html",
  styleUrls: ["./app.component.scss"],
})
export class AppComponent {
  title = "courses-app";
  @Input() text: string | undefined = "Harry Plotter";
  courses: any[] = [];

  ngOnInit(): void {
    this.getCourses().subscribe({
      next: (courses) => (this.courses = courses),
      error: (err) => console.error("Error loading courses:", err),
    });
  }

  getCourses(): Observable<any[]> {
    return of(mockedCoursesList);
  }
}

interface Course {
  title: string;
  description: string;
  creationDate: string;
  duration: string;
  authors: string[];
}
<app-header>
  <span>{{ text }}</span>
  <app-button buttonText="LOGOUT"></app-button>
</app-header>
<app-header>
  <app-button buttonText="LOGIN"></app-button>
</app-header>
<app-search placeholder="Input text"></app-search>
<div class="app-root">
  <app-course-card
    *ngFor="let course of courses"
    [title]="course.title"
    [description]="course.description"
    [editable]="course.editable"
    [authors]="course.authors"
    [duration]="course.duration"
    [creationDate]="course.creationDate"
  >
  </app-course-card>
  <!-- Search component -->

  <!-- Info component -->
  <app-info title="Angular" description="Some description"></app-info>

  <!-- Course Card component -->

  <!-- Login Form component -->
  <app-login-form></app-login-form>

  <!-- Login Form component -->
  <app-registration-form></app-registration-form>

  <!-- Login Form component -->
  <!--<app-course-form></app-course-form>-->

  <!-- Modal component -->
  <!-- <app-modal [message]="'Message'" [title]="'Title'" [okButtonText]="'Ok'" [cancelButtonText]="'Cancel'"></app-modal> -->
</div>
